-- LiveryLab Academy · individually reviewed, topic-specific fundamentals (Nov 2026)
-- Keep all lesson IDs, tasks, solutions, quizzes and progress unchanged.
WITH reviewed(lesson_id,theory) AS (VALUES
 ('lua-01','Mit print(...) zeigt Lua Werte in der Konsole an. Alles in den Klammern wird zuerst ausgewertet: print(2 + 3) zeigt 5, print("Hallo") zeigt den Text Hallo. Ohne Anführungszeichen sucht Lua nach einer Variablen. Du darfst eigene Namen und Texte verwenden, denn die Musterlösung ist nur ein Beispiel. Für mehrere getrennte Meldungen nutzt du mehrere print-Aufrufe. In FiveM helfen solche Ausgaben später dabei, den Ablauf eines Skripts zu kontrollieren.'),
 ('lua-02','Ein Kommentar erklärt Code für dich und andere, wird aber von Lua nicht ausgeführt. Mit -- kommentierst du den Rest einer Zeile; mit --[[ und ]] kannst du mehrere Zeilen beschreiben. print("-- Hallo") ist dagegen eine normale Textausgabe, weil die Striche innerhalb eines Strings stehen. Ein sinnvoller Kommentar erklärt vor allem, warum etwas geschieht, statt die nächste Zeile wortwörtlich zu wiederholen. Eine Startmeldung darunter bleibt ausführbarer Code.'),
 ('lua-03','Eine Variable speichert einen Wert unter einem Namen. Mit local spielerName = "Alex" legst du einen Text ab; local level = 5 speichert eine Zahl. print(spielerName, level) liest die aktuellen Werte aus, nicht die Beispielwerte aus der Lektion. Du kannst den Namen und den Level selbst bestimmen, solange du die erwarteten Variablen verwendest. local begrenzt ihre Sichtbarkeit auf den umgebenden Block. Verwechsle print(level) nicht mit print("level"): Das zweite gibt nur die Buchstaben aus.'),
 ('lua-04','Lua unterscheidet unter anderem number (Zahl), string (Text), boolean (true oder false) und nil (kein Wert). Mit type(preis) liest du den Datentyp, nicht den Zahlenwert. Deshalb liefert type(100) number und type("100") string. Eine Variable darf grundsätzlich ihren Wert und Typ ändern; für verlässliche Skripte solltest du aber vorher wissen, welcher Typ erwartet wird. Bei der Aufgabe darfst du eigene Zahlen und Texte einsetzen, musst aber preis, aktiv und titel mit den verlangten Typen anlegen.'),
 ('lua-05','Benutzereingaben kommen häufig als Text an. tonumber("50") versucht, daraus die Zahl 50 zu machen; bei nicht lesbaren Zahlen wie "abc" liefert es nil. tostring(50) wandelt umgekehrt eine Zahl in Text um. Bevor du rechnest, prüfe, ob tonumber wirklich eine Zahl zurückgegeben hat. Wenn die Aufgabe 50 plus 10 fordert, muss dein Programm die Zahlen korrekt umwandeln und addieren. So vermeidest du Fehler bei Commands, Formularen und FiveM-Spielerwerten.'),
 ('lua-06','Lua kann mit + addieren, mit - subtrahieren, mit * multiplizieren und mit / dividieren. In der Beispielrechnung stehen Preis und Rabatt in lokalen Variablen. Der Ausdruck preis - rabatt berechnet einen neuen Wert, der anschließend in endpreis gespeichert und mit print ausgegeben wird. Wenn der Preis 300 und der Rabatt 50 ist, muss das Ergebnis 250 sein. Die Operatoren % (Rest einer Division) und // (abgerundete Division) lösen andere Aufgaben. Achte auf die Reihenfolge der Rechenschritte.'),
 ('lua-07','Mit .. verbindest du in Lua zwei Texte, etwa "Willkommen " .. name. Die Variable name wird dabei durch ihren aktuellen Inhalt ersetzt; sie muss nicht Alex heißen. Beachte das Leerzeichen am Ende von "Willkommen ", sonst kleben beide Wörter zusammen. Für längere formatierte Texte kannst du string.format verwenden, etwa mit %s für einen String oder %d für eine ganze Zahl. In der Aufgabe soll die Begrüßung aus Text und einer lokalen Variable entstehen, nicht als kompletter fester Text.'),
 ('lua-08','Vergleiche in Lua ergeben die booleschen Werte true oder false. == fragt, ob zwei Werte gleich sind; ~= prüft Ungleichheit. Mit < und > vergleichst du Größen, mit <= und >= erlaubst du die Grenze ebenfalls. Ein einfaches = weist dagegen einer Variablen einen Wert zu und prüft keine Gleichheit. Bei level >= 5 ist das Ergebnis nur dann true, wenn level mindestens 5 ist. Solche Bedingungen entscheiden in FiveM beispielsweise über Levels, Jobs und Zugangsrechte.'),
 ('lua-09','Eine if-Bedingung führt einen Codeblock nur aus, wenn ihr Ausdruck wahr ist. Danach kannst du mit elseif weitere Fälle unterscheiden; else verarbeitet alles, was vorher nicht zutraf. Die Konstruktion endet mit end. Die Reihenfolge ist wichtig: Lua prüft die Bedingungen von oben nach unten und nimmt den ersten passenden Zweig. Für eine Level-Freischaltung ab 10 muss deshalb der Fall level >= 10 eindeutig vom gesperrten Fall getrennt sein. Teste jeweils einen Wert unter und einen über der Grenze.'),
 ('lua-10','Mit and müssen beide Bedingungen wahr sein; bei or genügt eine der beiden. not kehrt einen Wahrheitswert um. Lua wertet Ausdrücke von links nach rechts aus und überspringt bei and bzw. or unnötige Teile (Kurzschlussauswertung). Der Ausdruck player and player.job schützt deshalb vor dem Zugriff auf ein fehlendes Spielerobjekt. Wenn ein Zugang für police oder ambulance gelten soll, musst du die beiden Jobvergleiche ausdrücklich mit or verbinden. Ein bloßes or "ambulance" prüft den zweiten Job nicht korrekt.'),
 ('python-01','Python führt Anweisungen in der üblichen Reihenfolge von oben nach unten aus. Mit print("Hallo") gibst du einen Text aus; mit print(2 + 3) lässt du zuerst rechnen und zeigst danach 5 an. Texte benötigen Anführungszeichen, Namen ohne Anführungszeichen verweisen dagegen auf Variablen. Anders als manche Programmiersprachen nutzt Python für zusammengehörige Blöcke die Einrückung. Du kannst den Text im ersten Beispiel selbst austauschen und direkt sehen, wie sich die Ausgabe verändert.'),
 ('python-02','Eine Variable hält in Python einen Wert bereit, etwa name = "Mia" oder level = 7. Der Datentyp hängt vom gespeicherten Wert ab: ein String ist Text, ein int eine ganze Zahl und ein bool True oder False. print(name, level) zeigt die aktuellen Inhalte der beiden Variablen an; ein selbst gewählter Name und Level sind genauso richtig wie die Beispielwerte. Gute Variablennamen machen erkennbar, welche Information gespeichert wird. Prüfe mit type(name), welcher Datentyp tatsächlich vorliegt.'),
 ('python-03','Mit if triffst du in Python Entscheidungen. Hinter der Bedingung steht ein Doppelpunkt, und alle zugehörigen Anweisungen müssen eingerückt sein. else führt den alternativen Block aus, wenn die if-Bedingung nicht erfüllt ist. Bei geld >= 100 ist also wichtig, welchen Wert geld gerade hat. Ändere die Zahl im Beispiel und prüfe beide Zweige: einmal sollte "Kauf möglich", einmal "Zu wenig Geld" erscheinen. Einrückung ist in Python Teil der Syntax und nicht nur Dekoration.'),
 ('python-04','Eine Liste speichert mehrere Werte in einer bestimmten Reihenfolge. Du erstellst sie mit eckigen Klammern, zum Beispiel autos = ["Sultan", "Buffalo"]. Auf den ersten Eintrag greifst du mit autos[0] zu; der Index beginnt bei 0. Mit for auto in autos: gehst du die Einträge nacheinander durch und kannst jeden ausgeben oder verarbeiten. Die Schleife funktioniert auch mit selbst gewählten Autos und einer anderen Anzahl von Einträgen. Achte darauf, den eingerückten Schleifenkörper beizubehalten.'),
 ('python-05','Mit def legst du eine wiederverwendbare Funktion fest. Parameter wie preis und prozent sind Platzhalter, die beim Aufruf konkrete Werte erhalten. return gibt das berechnete Ergebnis an die aufrufende Stelle zurück, während print dieses Ergebnis lediglich anzeigt. Eine Rabattfunktion kann deshalb mit unterschiedlichen Preisen und Prozentwerten arbeiten, ohne jedes Mal neu geschrieben zu werden. Teste zum Beispiel zusätzlich einen Rabatt von 0 Prozent und prüfe, ob der Originalpreis zurückkommt.'),
 ('javascript-01','JavaScript kann im Browser oder mit Node.js ausgeführt werden. console.log(...) schreibt Werte in die Entwicklerkonsole und hilft dir, Zwischenergebnisse zu überprüfen. Mit let legst du eine Variable an, deren Wert du später erneut zuweisen darfst. let name = "Alex" und danach name = "Mia" verändern also den gespeicherten Inhalt; console.log(name) zeigt Mia. Ein eigener Name ist genauso gültig wie der Beispielwert. Verwechsle console.log(name) nicht mit console.log("name"): Das zweite zeigt nur das Wort name.'),
 ('javascript-02','Mit const deklarierst du eine Variablenbindung, die du später nicht auf einen anderen Wert umstellen kannst. Bei einfachen Zahlen oder Texten bleibt damit die Zuweisung fest. Bei Objekten und Arrays darfst du dagegen weiterhin deren Inhalte verändern, solange du die Variable nicht neu belegst. typeof liefert den Typ eines Werts, etwa number für 120 oder string für "120". Nutze das im Beispiel, um den Unterschied zwischen einem frei gewählten Zahlenwert und einem Textwert bewusst zu beobachten.'),
 ('javascript-03','Bedingungen steuern, welcher Code in JavaScript ausgeführt wird. Ein if-Block prüft einen Ausdruck, beispielsweise geld >= 100; ist er wahr, wird der zugehörige Zweig ausgeführt. Mit else legst du einen Alternativweg fest. Der Vergleich === prüft Wert und Datentyp, während == vor dem Vergleich Werte umwandeln kann und deshalb oft überraschende Ergebnisse liefert. Ändere im Beispiel den Geldbetrag und teste Werte oberhalb und unterhalb der Grenze, damit du beide Fälle verstehst.'),
 ('javascript-04','Ein Array sammelt mehrere Werte in einer festen Reihenfolge, zum Beispiel Fahrzeugnamen. map ruft für jeden Eintrag eine Funktion auf und erstellt aus den Rückgaben ein neues Array. Mit x => x.toUpperCase() wird jeder Name in Großbuchstaben umgewandelt; das ursprüngliche Array bleibt dabei unverändert. filter erfüllt eine andere Aufgabe: Es behält nur Elemente, auf die eine Bedingung passt. Probiere eigene Fahrzeugnamen aus, aber lass die map-Transformation erhalten, damit du das Konzept wirklich übst.'),
 ('javascript-05','JavaScript-Objekte fassen zusammengehörige Eigenschaften unter Schlüsseln zusammen. Ein spieler-Objekt kann beispielsweise name und ein weiteres Objekt job enthalten. Mit spieler.job.label greifst du auf den verschachtelten Wert zu. Fehlt job, würde der direkte Zugriff einen Fehler auslösen; spieler.job?.label gibt stattdessen undefined zurück. Optional Chaining ist besonders hilfreich bei unvollständigen API-Daten. Du darfst den Spielernamen oder Job ändern, solltest aber die Objektstruktur und den sicheren Zugriff beibehalten.')
), updated AS (
 UPDATE public.ll_lesson_content c
 SET payload=jsonb_set(c.payload,'{theory}',to_jsonb(r.theory),true)
 FROM reviewed r WHERE c.lesson_id=r.lesson_id
 AND c.payload->>'theory' IS DISTINCT FROM r.theory
 RETURNING c.lesson_id
)
SELECT count(*) AS updated_lessons FROM updated;